// src/data/lexikon.js
//
// Photovoltaik-Lexikon: EINZIGE Quelle fuer alle Fachbegriffe unter
// /wissen/lexikon. Seite, Suche, A–Z-Leiste und DefinedTermSet-JSON-LD ziehen
// sich alles hieraus.
//
// Aufbau je Eintrag:
//   id        Anker-ID (nur a–z, 0–9, Bindestrich) – NIE aendern, wird verlinkt
//   begriff   angezeigter Fachbegriff
//   buchstabe optional: Einordnung in der A–Z-Leiste (z. B. "§ 14a" unter P)
//   kurz      EIN zitierfaehiger Satz (Definition, fuer AI-Overviews/LLMs)
//   text      Erklaerung (2–4 Saetze, Orientierung Stand 2026)
//   kategorie eine aus KATEGORIEN
//   synonyme  optionale weitere Suchbegriffe
//   link      optional { href, label } auf passende Oekovolt-Seite/Rechner
//   verwandt  optionale ids verwandter Begriffe
//
// Stand: September 2026. Gesetzes- und Foerderangaben bei Aenderungen hier pflegen.

export const LEXIKON_STAND = "2026-09-13";

export const KATEGORIEN = [
  { id: "technik", label: "Technik & Module" },
  { id: "speicher", label: "Speicher & E-Mobilität" },
  { id: "wirtschaft", label: "Wirtschaftlichkeit" },
  { id: "recht", label: "Recht & Förderung" },
  { id: "netz", label: "Netz & Messung" },
];

export const BEGRIFFE = [
  // ---------------------------------------------------------------- A
  {
    id: "ac-kopplung",
    begriff: "AC-Kopplung",
    kurz: "Bei der AC-Kopplung wird ein Batteriespeicher mit eigenem Batteriewechselrichter auf der Wechselstromseite des Hausnetzes angeschlossen.",
    text: "Die AC-Kopplung ist die typische Lösung, um einen Speicher an eine bestehende PV-Anlage nachzurüsten, weil der vorhandene Wechselrichter bleiben kann. Da der Solarstrom zweimal umgewandelt wird (DC→AC→DC), sind die Verluste etwas höher als bei der DC-Kopplung.",
    kategorie: "speicher",
    verwandt: ["dc-kopplung", "hybridwechselrichter", "stromspeicher"],
    link: { href: "/produkte/stromspeicher", label: "Speicher nachrüsten" },
  },
  {
    id: "amortisation",
    begriff: "Amortisation",
    kurz: "Die Amortisationszeit ist der Zeitraum, nach dem die Einsparungen und Erlöse einer PV-Anlage ihre Anschaffungskosten vollständig gedeckt haben.",
    text: "Sie hängt vor allem vom Eigenverbrauch, vom Strompreis und von den Investitionskosten ab. Gut ausgelegte Einfamilienhaus-Anlagen amortisieren sich 2026 meist nach 10 bis 14 Jahren – bei einer technischen Lebensdauer von 25 Jahren und mehr.",
    kategorie: "wirtschaft",
    synonyme: ["Amortisationszeit", "Refinanzierung"],
    verwandt: ["eigenverbrauch", "stromgestehungskosten"],
    link: { href: "/solarrechner", label: "Amortisation berechnen" },
  },
  {
    id: "anschlussverguetung",
    begriff: "Anschlussvergütung (Ü20)",
    kurz: "Die Anschlussvergütung ist die befristete Vergütung zum Marktwert, die kleine PV-Anlagen nach Ablauf der 20-jährigen EEG-Förderung erhalten können.",
    text: "Betreiber ausgeförderter Anlagen bis 100 kW können ihren Strom weiter über den Netzbetreiber abgeben und bekommen dafür den Jahresmarktwert Solar abzüglich einer Vermarktungspauschale. Wirtschaftlich attraktiver ist oft die Umstellung auf Eigenverbrauch mit Speicher oder ein Repowering.",
    kategorie: "recht",
    synonyme: ["Ü20-Anlagen", "ausgeförderte Anlagen", "Post-EEG"],
    verwandt: ["eeg", "repowering", "direktvermarktung"],
    link: { href: "/service/repowering", label: "Repowering" },
  },
----
    link: { href: "/ratgeber/solaranlage-kosten#zusatz", label: "Zusatzkosten" },
  },
  {
    id: "zweirichtungszaehler",
    begriff: "Zweirichtungszähler",
    kurz: "Ein Zweirichtungszähler misst getrennt, wie viel Strom aus dem Netz bezogen und wie viel ins Netz eingespeist wird.",
    text: "Er ist Voraussetzung für die Abrechnung der Einspeisevergütung und wird bei Anmeldung der PV-Anlage vom Messstellenbetreiber gesetzt. Heute ist er in der Regel als moderne Messeinrichtung oder als Teil eines intelligenten Messsystems ausgeführt.",
    kategorie: "netz",
    synonyme: ["Einspeisezähler", "bidirektionaler Zähler"],
    verwandt: ["moderne-messeinrichtung", "imsys", "einspeiseverguetung"],
  },
  {
    id: "zyklenfestigkeit",
    begriff: "Zyklenfestigkeit",
    kurz: "Die Zyklenfestigkeit gibt an, wie viele vollständige Lade- und Entladevorgänge ein Batteriespeicher durchlaufen kann, bevor seine Kapazität unter einen festgelegten Wert fällt.",
    text: "Moderne LFP-Heimspeicher sind auf 6.000 und mehr Vollzyklen ausgelegt. Bei rund 250 Zyklen im Jahr entspricht das weit über 15 Jahren Nutzung; Hersteller garantieren meist 10 Jahre und eine Restkapazität von 60 bis 80 %.",
    kategorie: "speicher",
    synonyme: ["Vollzyklen", "Lebensdauer Speicher"],
    verwandt: ["lfp", "stromspeicher", "speicherkapazitaet"],
  },
];

/** Buchstabe für die A–Z-Leiste (Umlaute zum Grundbuchstaben). */
export function buchstabeVon(b) {
  if (b.buchstabe) return b.buchstabe;
  const c = b.begriff.trim().charAt(0).toUpperCase();
  return { Ä: "A", Ö: "O", Ü: "U" }[c] || c;
}

/** Begriffe alphabetisch, gruppiert nach Buchstaben. */
export function begriffeNachBuchstabe() {
  const sortiert = [...BEGRIFFE].sort((a, b) => a.begriff.localeCompare(b.begriff, "de"));
  const gruppen = new Map();
  for (const b of sortiert) {
    const l = buchstabeVon(b);
    if (!gruppen.has(l)) gruppen.set(l, []);
    gruppen.get(l).push(b);
  }
  return [...gruppen.entries()].sort(([a], [b]) => a.localeCompare(b, "de"));
}
