// src/data/lexikon.js
//
// Fachlexikon ÖkoInvest: EINZIGE Quelle für alle Fachbegriffe unter
// /wissen/lexikon (Projektentwicklung Freiflächen-PV, Agri-PV, Solarcarports,
// Großspeicher, Projektbörse, Investment, virtuelles Kraftwerk, Reststrom-Pool
// und Energiegemeinschaften im DACH-Raum). Seite, Suche, A–Z-Leiste und
// DefinedTermSet-JSON-LD ziehen sich alles hieraus.
//
// Aufbau je Eintrag:
//   id        Anker-ID (nur a–z, 0–9, Bindestrich) – NIE ändern, wird verlinkt
//   begriff   angezeigter Fachbegriff
//   buchstabe optional: Einordnung in der A–Z-Leiste (z. B. "§ 6" unter K)
//   kurz      EIN zitierfähiger Satz (Definition, für AI-Overviews/LLMs)
//   text      Erklärung (2–4 Sätze, Orientierung Stand 2026)
//   kategorie eine aus KATEGORIEN
//   synonyme  optionale weitere Suchbegriffe
//   link      optional { href, label } auf passende ÖkoInvest-Seite/Rechner/Ratgeber
//   verwandt  optionale ids verwandter Begriffe
//
// Zahlen kommen, wo möglich, aus src/lib/invest/markt.js, damit Lexikon,
// Rechner und Seiten dieselben Werte nennen.
//
// Stand: September 2026. Gesetzes- und Förderangaben bei Änderungen hier pflegen.

import { PACHT, AGRI, PHASEN, PROVISION, KOMMUNE, ERLOESE, FREIFLAECHE, STROM, FINANZIERUNG } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

const RTB = PHASEN.find((p) => p.id === "rtb");
const BESTAND = PHASEN.find((p) => p.id === "cod");
const FLAECHE = PHASEN.find((p) => p.id === "flaeche");
const pct = (x, stellen = 0) => `${fmt(x * 100, stellen)} %`;

export const LEXIKON_STAND = "2026-09-29";

export const KATEGORIEN = [
  { id: "planung", label: "Planung & Genehmigung" },
  { id: "flaeche", label: "Fläche & Landwirtschaft" },
  { id: "technik", label: "Technik & Netz" },
  { id: "markt", label: "Strommarkt & Vermarktung" },
  { id: "invest", label: "Investment & Transaktion" },
  { id: "gemeinschaft", label: "Gemeinschaften & DACH" },
];

export const BEGRIFFE = [
  // ---------------------------------------------------------------- A
  {
    id: "agri-pv",
    begriff: "Agri-Photovoltaik (Agri-PV)",
    kurz: "Agri-PV ist die gleichzeitige Nutzung derselben Fläche für landwirtschaftliche Produktion und Solarstromerzeugung, wobei die Landwirtschaft die Hauptnutzung bleibt.",
    text: `Üblich sind hoch aufgeständerte Systeme über Sonderkulturen und vertikale, bifaziale Modulreihen auf Acker oder Grünland, zwischen denen bewirtschaftet wird. In Deutschland beschreibt die DIN SPEC 91434 die Anforderungen; bleiben die Kriterien erfüllt, sind nach aktuellem Stand rund ${pct(AGRI.gapFoerderfaehig)} der Fläche weiter GAP-förderfähig. Agri-PV gehört im EEG zu den besonderen Solaranlagen und kann bis ${fmt(AGRI.privilegierungHa, 1)} ha mit Hofbezug im Außenbereich privilegiert sein.`,
    kategorie: "flaeche",
    synonyme: ["Agrivoltaik", "Agrophotovoltaik", "APV"],
    verwandt: ["din-spec-91434", "gap-direktzahlungen", "besondere-solaranlagen", "privilegierung-aussenbereich"],
    link: { href: "/agri-pv", label: "Agri-PV mit ÖkoInvest" },
  },
  {
    id: "anlagenzertifikat",
    begriff: "Anlagenzertifikat",
    kurz: "Das Anlagenzertifikat bescheinigt, dass eine Erzeugungs- oder Speicheranlage die netztechnischen Anforderungen der jeweiligen VDE-Anwendungsregel am Netzanschlusspunkt erfüllt.",
    text: "Für Anlagen am Mittelspannungsnetz (VDE-AR-N 4110) und Hochspannungsnetz (VDE-AR-N 4120) verlangt der Netzbetreiber in der Regel ab einer bestimmten Anlagengröße ein Anlagenzertifikat, für kleinere Anlagen teils ein vereinfachtes Verfahren. Es wird von einer akkreditierten Zertifizierungsstelle auf Basis von Einheitenzertifikaten und Netzberechnungen erstellt und ist Voraussetzung für die Inbetriebsetzung. Zeitbedarf und Kosten sollten früh im Projektplan berücksichtigt werden.",
    kategorie: "technik",
    synonyme: ["VDE-AR-N 4110", "Einheitenzertifikat", "Konformitätserklärung"],
    verwandt: ["netzverknuepfungspunkt", "cod", "umspannwerk"],
    link: { href: "/prozess", label: "Projektablauf" },
  },
  {
    id: "anzulegender-wert",
    begriff: "Anzulegender Wert",
    kurz: "Der anzulegende Wert ist im EEG der Betrag in Cent je Kilowattstunde, auf dessen Basis die Marktprämie einer geförderten Anlage berechnet wird.",
    text: `Bei ausschreibungspflichtigen Anlagen entspricht er dem eigenen Zuschlagswert (Gebotspreis); bei kleineren Anlagen ist er gesetzlich festgelegt. Die Marktprämie ergibt sich aus der Differenz zwischen anzulegendem Wert und Marktwert Solar und gilt in der Regel 20 Jahre. Zur Orientierung: Im ersten Segment lagen die durchschnittlichen Zuschlagswerte zuletzt bei rund ${fmt(ERLOESE.eegFreiflaecheCt, 1)} ct/kWh.`,
    kategorie: "markt",
    verwandt: ["marktpraemie", "zuschlagswert", "marktwert-solar", "ausschreibung-eeg"],
    link: { href: "/ratgeber/eeg-ausschreibung-freiflaeche", label: "EEG-Ausschreibung erklärt" },
  },
  {
    id: "arbitrage",
    begriff: "Arbitrage (Strom)",
    kurz: "Arbitrage bezeichnet das Ausnutzen von Preisunterschieden am Strommarkt, indem ein Speicher zu günstigen Zeiten lädt und zu teuren Zeiten entlädt.",
    text: "Für Batteriegroßspeicher ist die Arbitrage im Day-Ahead- und Intraday-Handel neben der Regelenergie die wichtigste Erlösquelle. Die Erlöse hängen von der Preisvolatilität, dem Wirkungsgrad und der Zyklenzahl ab; hohe Solareinspeisung zur Mittagszeit und negative Preise vergrößern die Spreads. In der Praxis wird der Speicher über einen Optimierer oder ein virtuelles Kraftwerk vermarktet.",
    kategorie: "markt",
    synonyme: ["Energiearbitrage", "Spread-Handel", "Intraday-Handel"],
    verwandt: ["grossspeicher", "regelenergie", "negative-strompreise", "virtuelles-kraftwerk"],
    link: { href: "/ratgeber/grossspeicher-erloese", label: "Erlöse von Großspeichern" },
  },
  {
    id: "asset-deal",
    begriff: "Asset Deal",
    kurz: "Beim Asset Deal kauft der Investor einzelne Vermögensgegenstände eines Projekts – etwa Verträge, Genehmigungen und Anlagenteile – statt Anteile an der Projektgesellschaft.",
    text: "Der Käufer kann gezielt auswählen, welche Rechte und Pflichten er übernimmt, und vermeidet so unbekannte Altlasten der Gesellschaft. Dafür muss jeder Vertrag einzeln übertragen werden, was Zustimmungen von Verpächtern, Netzbetreiber oder Behörden erfordern kann. In der Projektentwicklung ist deshalb häufiger der Share Deal üblich.",
    kategorie: "invest",
    verwandt: ["share-deal", "spa", "projektrechte", "due-diligence"],
    link: { href: "/ratgeber/projektrechte-kaufen-due-diligence", label: "Projektrechte kaufen" },
  },
  {
    id: "aufstellungsbeschluss",
    begriff: "Aufstellungsbeschluss",
    kurz: "Der Aufstellungsbeschluss ist der Beschluss des Gemeinderats, einen Bebauungsplan für ein bestimmtes Gebiet aufzustellen, und startet damit das förmliche Bauleitplanverfahren.",
    text: "Mit ihm bekundet die Gemeinde ihren Planungswillen; ein Anspruch auf Baurecht entsteht dadurch noch nicht. Für Solarparks ist er ein wichtiger Meilenstein, weil er zeigt, dass die Kommune das Vorhaben grundsätzlich mitträgt – Projekte in dieser Phase werden am Markt entsprechend höher bewertet als reine Flächensicherungen. Häufig wird parallel ein städtebaulicher Vertrag über die Kostenübernahme geschlossen.",
    kategorie: "planung",
    verwandt: ["bebauungsplan", "fruehzeitige-beteiligung", "satzungsbeschluss", "flaechennutzungsplan"],
    link: { href: "/ratgeber/solarpark-genehmigung-bebauungsplan", label: "B-Plan-Verfahren" },
  },
  {
    id: "ausgleichsflaechen",
    begriff: "Ausgleichsflächen",
    kurz: "Ausgleichsflächen sind Flächen, auf denen Eingriffe in Natur und Landschaft nach der naturschutzrechtlichen Eingriffsregelung kompensiert werden.",
    text: "Im Bebauungsplanverfahren für einen Solarpark wird der Eingriff bilanziert und ein Ausgleich festgelegt. Weil extensiv gepflegtes Grünland unter und zwischen den Modulreihen ökologisch oft aufgewertet wird, kann ein großer Teil des Ausgleichs in der Regel innerhalb der Anlagenfläche erbracht werden, etwa durch Blühstreifen, Hecken oder Beweidung. Umfang und Anrechnung regeln die Länder und die Kommune unterschiedlich.",
    kategorie: "planung",
    synonyme: ["Kompensationsflächen", "Eingriffsregelung"],
    verwandt: ["umweltbericht", "bebauungsplan", "uvp"],
    link: { href: "/freiflaeche", label: "Freiflächen-PV" },
  },
  {
    id: "ausschreibung-eeg",
    begriff: "Ausschreibung (EEG)",
    kurz: "In der EEG-Ausschreibung ermittelt die Bundesnetzagentur im Wettbewerb, welche Solarprojekte eine Marktprämie erhalten und zu welchem anzulegenden Wert.",
    text: "Freiflächenanlagen über 1 MW nehmen in der Regel an den Ausschreibungen des ersten Segments teil; die Projekte bieten verdeckt einen Preis in ct/kWh, und die günstigsten Gebote erhalten bis zum Ausschreibungsvolumen einen Zuschlag (pay-as-bid). Voraussetzung sind unter anderem eine Fläche in der Flächenkulisse, ein aufgestellter oder beschlossener Bebauungsplan und eine Sicherheitsleistung. Nach dem Zuschlag muss die Anlage innerhalb einer Frist realisiert werden, sonst drohen Pönalen.",
    kategorie: "markt",
    synonyme: ["Solarausschreibung", "erstes Segment"],
    verwandt: ["gebotstermin", "zuschlagswert", "flaechenkulisse", "besondere-solaranlagen"],
    link: { href: "/ratgeber/eeg-ausschreibung-freiflaeche", label: "EEG-Ausschreibung Freifläche" },
  },

  // ---------------------------------------------------------------- B
  {
    id: "baukostenzuschuss",
    begriff: "Baukostenzuschuss (BKZ)",
    kurz: "Der Baukostenzuschuss ist ein einmaliger Beitrag, den ein Netzbetreiber beim Netzanschluss für die anteiligen Kosten des vorgelagerten Netzausbaus verlangen kann.",
    text: "Für reine Erzeugungsanlagen wie Solarparks fällt in Deutschland in der Regel kein Baukostenzuschuss an. Bei Batteriegroßspeichern, die Strom auch aus dem Netz beziehen, dürfen Netzbetreiber nach der Rechtsprechung des Bundesgerichtshofs (2025) hingegen einen BKZ erheben; seine Höhe hängt von Netzebene und Anschlussleistung ab und kann die Wirtschaftlichkeit deutlich beeinflussen. Für Speicherprojekte gehört er daher früh in die Kalkulation.",
    kategorie: "technik",
    synonyme: ["BKZ", "Netzkostenbeitrag"],
    verwandt: ["grossspeicher", "netzanschlusszusage", "netzverknuepfungspunkt"],
    link: { href: "/grossspeicher", label: "Großspeicher" },
  },
  {
    id: "bebauungsplan",
    begriff: "Bebauungsplan (B-Plan)",
    kurz: "Der Bebauungsplan ist die gemeindliche Satzung, die für ein bestimmtes Gebiet verbindlich festlegt, was dort gebaut werden darf – für die meisten Solarparks ist er die Grundlage des Baurechts.",
    text: "Weil Freiflächen-PV im Außenbereich nur in Ausnahmefällen privilegiert ist, schafft die Gemeinde das Baurecht in der Regel über einen vorhabenbezogenen oder Angebots-Bebauungsplan, meist als Sondergebiet Photovoltaik. Das Verfahren umfasst Aufstellungsbeschluss, frühzeitige und förmliche Beteiligung, Umweltbericht und Satzungsbeschluss und dauert typischerweise ein bis zwei Jahre. Häufig wird der Flächennutzungsplan im Parallelverfahren geändert.",
    kategorie: "planung",
    synonyme: ["B-Plan", "vorhabenbezogener Bebauungsplan", "Sondergebiet Photovoltaik"],
    verwandt: ["aufstellungsbeschluss", "satzungsbeschluss", "flaechennutzungsplan", "umweltbericht"],
    link: { href: "/ratgeber/solarpark-genehmigung-bebauungsplan", label: "Genehmigung eines Solarparks" },
  },
  {
    id: "benachteiligte-gebiete",
    begriff: "Benachteiligte Gebiete",
    kurz: "Benachteiligte Gebiete sind nach EU-Agrarrecht abgegrenzte landwirtschaftliche Flächen mit ungünstigen natürlichen Bedingungen, auf denen Freiflächen-PV an EEG-Ausschreibungen teilnehmen kann.",
    text: "Ursprünglich mussten die Länder diese Acker- und Grünlandflächen per Verordnung für Solarparks öffnen (Länderöffnungsklausel). Seit dem Solarpaket I sind sie grundsätzlich Teil der Flächenkulisse; die Länder können sie nach aktuellem Stand unter bestimmten Voraussetzungen wieder einschränken. Ob eine Fläche in einem benachteiligten Gebiet liegt, lässt sich über die Agrarverwaltung des Landes prüfen.",
    kategorie: "flaeche",
    synonyme: ["Länderöffnungsklausel", "benachteiligtes Gebiet"],
    verwandt: ["flaechenkulisse", "ausschreibung-eeg", "randstreifen"],
    link: { href: "/flaechencheck", label: "Fläche prüfen" },
  },
  {
    id: "besondere-solaranlagen",
    begriff: "Besondere Solaranlagen",
    kurz: "Besondere Solaranlagen sind im EEG Agri-PV-, Floating-, Moor- und Parkplatz-PV-Anlagen, für die eigene Anforderungen und in den Ausschreibungen ein eigenes Segment mit gesonderten Höchstwerten gelten.",
    text: `Weil diese Anlagen mehr kosten als klassische Freiflächenanlagen, werden sie in der Ausschreibung nicht direkt mit ihnen verglichen; die Zuschlagswerte lagen zuletzt spürbar höher, zur Orientierung bei rund ${fmt(ERLOESE.eegBesondereCt, 1)} ct/kWh. Welche Anforderungen im Einzelnen gelten, legt die Bundesnetzagentur fest; für Agri-PV wird dabei in der Regel auf die DIN SPEC 91434 verwiesen.`,
    kategorie: "markt",
    synonyme: ["Agri-PV", "Floating-PV", "Moor-PV", "Parkplatz-PV"],
    verwandt: ["agri-pv", "ausschreibung-eeg", "din-spec-91434", "flaechenkulisse"],
    link: { href: "/ratgeber/agri-pv-wirtschaftlichkeit", label: "Wirtschaftlichkeit Agri-PV" },
  },
  {
    id: "bifazial",
    begriff: "Bifaziale Module",
    kurz: "Bifaziale Solarmodule nehmen Licht auf Vorder- und Rückseite auf und nutzen so auch das vom Boden reflektierte Licht.",
    text: "Der Mehrertrag gegenüber monofazialen Modulen liegt je nach Bodenreflexion und Aufständerung meist im einstelligen Prozentbereich. Bei vertikalen Agri-PV-Anlagen in Ost-West-Ausrichtung sind bifaziale Module Voraussetzung: Sie erzeugen Spitzen am Vormittag und Nachmittag, wenn Strom oft mehr wert ist als zur Mittagszeit.",
    kategorie: "technik",
    synonyme: ["Bifazialität", "Glas-Glas-Module"],
    verwandt: ["agri-pv", "tracker", "spezifischer-ertrag", "capture-rate"],
    link: { href: "/rechner/agri-pv", label: "Agri-PV-Rechner" },
  },
  {
    id: "buergerenergiegemeinschaft",
    begriff: "Bürgerenergiegemeinschaft (BEG)",
